import{_ as r,o,c as s,a2 as a}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"VF 薯条脆 · 片型可行性分析","description":"","frontmatter":{},"headers":[],"relativePath":"cases/case-04-fries-crisp-formats.md","filePath":"cases/case-04-fries-crisp-formats.md","lastUpdated":1786871523000}'),d={name:"cases/case-04-fries-crisp-formats.md"};function n(e,t,l,i,p,h){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="vf-薯条脆-·-片型可行性分析" tabindex="-1">VF 薯条脆 · 片型可行性分析 <a class="header-anchor" href="#vf-薯条脆-·-片型可行性分析" aria-label="Permalink to &quot;VF 薯条脆 · 片型可行性分析&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">这是教学演示内容</p><p>配合 <a href="/cases/case-04-vf-fries-crisp">案例 04 · VF 工艺薯条脆</a> 阅读。回答的是那个案例<strong>动手之前</strong>的问题：这个产品到底该拍什么类型的片子。</p><p>产品设定与合规判断沿用案例 04，<strong>不是真实客户项目的复盘</strong>。</p></div><blockquote><p><strong>一句话</strong>：片型不是选出来的，是被产品条件<strong>排除</strong>到只剩一两个的。</p></blockquote><hr><h2 id="为什么要单独做这一步" tabindex="-1">为什么要单独做这一步 <a class="header-anchor" href="#为什么要单独做这一步" aria-label="Permalink to &quot;为什么要单独做这一步&quot;">​</a></h2><p>案例 04 直接从「客户要讲工艺」跳到了分镜。实际项目里中间还有一步：<strong>确认「讲工艺」应该长成什么形态的片子</strong>。</p><p>这一步做错，后面全白做。它比 <a href="/method/big-idea">Big Idea</a> 更靠前——Big Idea 决定「说什么」，片型决定「用什么容器装」。容器错了，再好的内容也漏出来。</p><p>通用的片型清单、创意手法层和选型排除法，见 <a href="/method/ad-formats">片型图谱：这支片子该长什么样</a>。<strong>本篇是那套方法在一个具体产品上的完整落地</strong>，两篇对照着读价值最大。</p><div class="tip custom-block"><p class="custom-block-title">判断顺序</p><p>产品条件 → 排除不可行的片型 → 剩下的里选投放场景匹配的 → 才轮到想创意。</p><p><strong>不是</strong>先想一个好创意，再找地方放。</p></div><hr><h2 id="_1-产品条件盘点" tabindex="-1">① 产品条件盘点 <a class="header-anchor" href="#_1-产品条件盘点" aria-label="Permalink to &quot;① 产品条件盘点&quot;">​</a></h2><p>动手评估片型之前，先把这个产品的硬条件列清楚。<strong>每一条都会否掉某些片型。</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>VF 薯条脆的情况</th><th>对片型的影响</th></tr></thead><tbody><tr><td><strong>差异化落在哪一层</strong></td><td>工艺层（VF 真空低温油炸）</td><td>口味层、品牌层都没东西可说，片子必须能承载&quot;过程&quot;</td></tr><tr><td><strong>感官抓手</strong></td><td>只有「脆」</td><td>见下方专门说明，这是最容易被忽略的一条</td></tr><tr><td><strong>决策链路</strong></td><td>电商详情页 = 说服型决策</td><td>需要&quot;给理由&quot;，不是纯情绪煽动</td></tr><tr><td><strong>产品体量</strong></td><td>单品、低客单价休闲零食</td><td>撑不起品牌故事片的体量</td></tr><tr><td><strong>合规敏感度</strong></td><td>高——食品广告 + 工艺宣称双重约束</td><td>直接否掉两类片型，见 ③</td></tr><tr><td><strong>AI 适配度</strong></td><td>长板明显、短板也明显</td><td>长板：工艺内部、微观结构；短板：包装文字、真人表演</td></tr></tbody></table><h3 id="那条最容易被忽略的-这个产品没有「热」" tabindex="-1">那条最容易被忽略的：这个产品没有「热」 <a class="header-anchor" href="#那条最容易被忽略的-这个产品没有「热」" aria-label="Permalink to &quot;那条最容易被忽略的：这个产品没有「热」&quot;">​</a></h3><p><a href="/cases/case-03-fries-social">案例 03</a> 总结的食欲感四要素是<strong>热气、质感对比、油脂光泽、动作</strong>。四条里热气最强——热=刚做好=新鲜。</p><p>但薯条脆是<strong>预包装常温零食</strong>。</p><table tabindex="0"><thead><tr><th>食欲要素</th><th>快餐现炸薯条</th><th>VF 薯条脆</th></tr></thead><tbody><tr><td>热气</td><td>✅ 核心抓手</td><td>❌ <strong>不存在</strong></td></tr><tr><td>质感对比（断面）</td><td>✅ 外脆内软</td><td>✅ 蜂窝气孔，且更独特</td></tr><tr><td>油脂光泽</td><td>✅</td><td>⚠️ 弱，且不宜强调（往油上引不利）</td></tr><tr><td>动作（蘸取、拿起）</td><td>✅ 蘸番茄酱</td><td>⚠️ 弱，袋装零食没有标志性动作</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">这个差异决定了不能照抄案例 03</p><p>四要素里<strong>两条失效、一条不宜用</strong>，只剩「质感对比」一条完好。</p><p>如果直接套用案例 03 的拍法，你会拍出一支&quot;少了一半信息量&quot;的食欲片——观众说不上哪里不对，就是不馋。</p><p>**同品类不等于同拍法。**薯条和薯条脆看着像，感官条件完全是两回事。</p></div><p>补偿方案：<strong>把声音提到视觉同等的位置</strong>。没有热气可看，但「脆」是可听的。片与片碰撞的清脆声、掰断的干脆响、咀嚼的碎裂声——这些在案例 03 里是加分项，在这里是<strong>必需项</strong>。</p><hr><h2 id="_2-片型逐一评估" tabindex="-1">② 片型逐一评估 <a class="header-anchor" href="#_2-片型逐一评估" aria-label="Permalink to &quot;② 片型逐一评估&quot;">​</a></h2><table tabindex="0"><thead><tr><th>片型</th><th>适配度</th><th>一句话结论</th></tr></thead><tbody><tr><td><strong>工艺解构片</strong></td><td>★★★★★</td><td>唯一能承载差异化的形态，且 AI 优势最大</td></tr><tr><td><strong>感官 ASMR 片</strong></td><td>★★★☆☆</td><td>可做，但要改造——靠声音补上失效的热气</td></tr><tr><td><strong>对比片</strong></td><td>✕</td><td>法律风险，不是创意选择</td></tr><tr><td><strong>代言人口播 / 达人测评</strong></td><td>✕</td><td>合规 + AI 短板双重踩雷</td></tr><tr><td><strong>品牌情感故事片</strong></td><td>✕</td><td>体量不匹配，观众也没耐心</td></tr></tbody></table><p>下面逐条展开。</p><hr><h3 id="★★★★★-工艺解构片" tabindex="-1">★★★★★ 工艺解构片 <a class="header-anchor" href="#★★★★★-工艺解构片" aria-label="Permalink to &quot;★★★★★ 工艺解构片&quot;">​</a></h3><p>**这是案例 04 实际采用的路线。**理由是三层叠加，不是单一原因：</p><table tabindex="0"><thead><tr><th>理由</th><th>说明</th></tr></thead><tbody><tr><td><strong>它的差异化只有工艺</strong></td><td>薯条脆品类高度同质化，VF 是唯一能拿出来说的东西。不讲工艺，这支片子就没有内容</td></tr><tr><td><strong>核心画面实拍不到</strong></td><td>真空罐内部、水分汽化、蜂窝断面——实拍要么不可能要么极贵，<strong>AI 在这类画面上相对优势最大</strong></td></tr><tr><td><strong>匹配投放场景</strong></td><td>电商详情页要的是&quot;说服&quot;。原料→工艺→结果→产品 的骨架比讲故事更有效</td></tr></tbody></table><p><strong>唯一的强约束</strong>：只展示做法，不展示好处。</p><p>「更健康」「低脂」「非油炸」「0 负担」全是红线。展示过程，让消费者自己下结论——<strong>你替他下的结论他不信，他自己下的结论他才信</strong>。完整的合规边界见 <a href="/cases/case-04-vf-fries-crisp">案例 04 的限制条件</a>。</p><div class="tip custom-block"><p class="custom-block-title">为什么这个片型在 AI 时代性价比特别高</p><p>放在五年前，工艺解构片是<strong>最贵</strong>的片型之一——要么进车间实拍（设备封闭，根本拍不到），要么做三维动画（周期以月计）。</p><p>现在它变成了<strong>最便宜</strong>的片型之一。这个成本结构的翻转，是&quot;技术卖点类产品该不该拍工艺片&quot;这个问题在今天有了新答案的原因。</p></div><hr><h3 id="★★★☆☆-感官-asmr-片" tabindex="-1">★★★☆☆ 感官 ASMR 片 <a class="header-anchor" href="#★★★☆☆-感官-asmr-片" aria-label="Permalink to &quot;★★★☆☆ 感官 ASMR 片&quot;">​</a></h3><p>可以做，但<strong>必须改造</strong>，不能照搬 <a href="/cases/case-03-fries-social">案例 03</a>。</p><table tabindex="0"><thead><tr><th>改造点</th><th>怎么改</th></tr></thead><tbody><tr><td>热气失效</td><td>删掉所有蒸汽镜头。硬加热气反而穿帮——袋装零食冒热气不合理</td></tr><tr><td>声音升级为主角</td><td>音效不是配的，是<strong>拍的</strong>。碰撞声、断裂声、咀嚼碎裂声，每一条单独设计</td></tr><tr><td>断面成为唯一视觉核心</td><td>蜂窝气孔透光比普通薯条的粉质断面<strong>更独特</strong>，这是它的优势，要吃透</td></tr><tr><td>补一个动作</td><td>袋装零食缺标志性动作，可用&quot;倒出&quot;&quot;抓取&quot;&quot;片片叠落&quot;顶上</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">一个反直觉的结论</p><p>感官片对这个产品来说，<strong>不能单独存在</strong>。</p><p>原因：纯感官片讲不了工艺，而工艺是它唯一的差异化。观众看完只知道&quot;这玩意儿看着挺脆&quot;——但市面上所有薯片都脆，你没有给出选你的理由。</p><p>所以它只能是<strong>组合拳里的一半</strong>，见 ④。</p></div><hr><h3 id="✕-对比片" tabindex="-1">✕ 对比片 <a class="header-anchor" href="#✕-对比片" aria-label="Permalink to &quot;✕ 对比片&quot;">​</a></h3><p>客户最常提的诉求，<strong>也是必须挡回去的那个</strong>。</p><p>左边传统油炸、右边 VF——这个结构效果确实好，但直接对比同类产品容易构成<strong>贬低同类</strong>，在广告法下有明确风险。</p><div class="danger custom-block"><p class="custom-block-title">这是法律问题，不是创意问题</p><p>和客户沟通时要说清楚这个定性。说成&quot;我觉得效果不好&quot;会被推翻，说成&quot;这条有法律风险，我们不能做&quot;才站得住。</p><p><strong>替代方案</strong>：只展示自己的工艺，不出现任何参照物。观众的对比是在他自己脑子里完成的——<strong>而且他自己脑补的对比，比你摆在屏幕上的更有说服力</strong>。</p></div><hr><h3 id="✕-代言人口播-达人测评" tabindex="-1">✕ 代言人口播 / 达人测评 <a class="header-anchor" href="#✕-代言人口播-达人测评" aria-label="Permalink to &quot;✕ 代言人口播 / 达人测评&quot;">​</a></h3><p>两个问题叠加，任何一个单独都足以否掉：</p><table tabindex="0"><thead><tr><th>问题</th><th>说明</th></tr></thead><tbody><tr><td><strong>合规</strong></td><td>口播讲工艺，一张嘴就容易滑向&quot;更健康&quot;&quot;比油炸的好&quot;。真人说出来比字幕更像&quot;承诺&quot;，风险更高</td></tr><tr><td><strong>AI 短板</strong></td><td>真人表演、口型同步、微表情——这是生成模型目前最弱的一环，见 <a href="/prompts/spokesperson">人物代言</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">如果客户坚持要真人</p><p>这一类<strong>不要用 AI 做</strong>。真人出镜的内容，找真人拍，成本反而更低、风险更小。</p><p>AI 广告的能力边界要诚实划出来。硬用 AI 做真人口播，是拿自己的短板去打别人的长板。</p></div><hr><h3 id="✕-品牌情感故事片" tabindex="-1">✕ 品牌情感故事片 <a class="header-anchor" href="#✕-品牌情感故事片" aria-label="Permalink to &quot;✕ 品牌情感故事片&quot;">​</a></h3><p>三个不匹配：</p><ul><li><strong>体量不匹配</strong>：低客单价单品，情感故事片的制作成本回不来</li><li><strong>注意力不匹配</strong>：信息流里没人为一袋薯片看完 60 秒的故事</li><li><strong>阶段不匹配</strong>：品牌片是有品牌资产之后的事，一个靠工艺切入市场的新品，先把&quot;为什么值得买&quot;讲清楚</li></ul><div class="tip custom-block"><p class="custom-block-title">什么时候可以做</p><p>等这个产品跑出量、要建立品类心智的时候。<strong>现在做，是在正确的事情上抢错了时机。</strong></p></div><hr><h2 id="_3-合规是片型筛子-不是最后一道检查" tabindex="-1">③ 合规是片型筛子，不是最后一道检查 <a class="header-anchor" href="#_3-合规是片型筛子-不是最后一道检查" aria-label="Permalink to &quot;③ 合规是片型筛子，不是最后一道检查&quot;">​</a></h2><p>注意上面五个片型里，<strong>有两个是被合规直接否掉的</strong>，而不是被创意质量否掉的。</p><p>这是工艺类食品项目和普通项目最大的结构差异：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通项目：  想创意 → 选片型 → 做出来 → 法务检查 → 小改</span></span>
<span class="line"><span>工艺食品：  合规边界 → 排除片型 → 在剩下的里想创意 → 法务复核</span></span>
<span class="line"><span>                ↑</span></span>
<span class="line"><span>          它在最前面，不在最后面</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">把合规放在最后会怎样</p><p>你会做出一支很好的对比片，然后在法务环节被整个砍掉——<strong>不是改文案能救的那种砍掉，是重做</strong>。</p><p>案例 04 的工期里，四天有整整一天花在核查和审校上，不产出任何画面。这个成本必须计入报价，否则你是在免费做法务工作。</p></div><hr><h2 id="_4-推荐组合拳-详情页-种草" tabindex="-1">④ 推荐组合拳：详情页 + 种草 <a class="header-anchor" href="#_4-推荐组合拳-详情页-种草" aria-label="Permalink to &quot;④ 推荐组合拳：详情页 + 种草&quot;">​</a></h2><p>单独任何一支都有缺口。<strong>两支配合投放，缺口互补</strong>：</p><table tabindex="0"><thead><tr><th></th><th>工艺解构片</th><th>感官 ASMR 片</th></tr></thead><tbody><tr><td><strong>投放位</strong></td><td>电商详情页</td><td>抖音 / 小红书信息流</td></tr><tr><td><strong>时长</strong></td><td>20 秒</td><td>8–10 秒</td></tr><tr><td><strong>回答的问题</strong></td><td>为什么值得买</td><td>想吃</td></tr><tr><td><strong>观众状态</strong></td><td>已经点进来了，愿意看理由</td><td>刷到的，只给你两秒</td></tr><tr><td><strong>开头</strong></td><td>原料入场</td><td><strong>直接上断面透光</strong>，不要铺垫</td></tr><tr><td><strong>结尾</strong></td><td>包装 + 工艺字幕</td><td>包装一闪，不解释</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">两支片子共用素材</p><p>断面镜头、成品掉落镜头两支都要用。<strong>一次生成，两处使用</strong>——这是降低生成成本最直接的办法。</p><p>排期上先做工艺片（要求更高、返工更多），感官片从它的素材里剪，能省掉大半工作量。</p></div><hr><h2 id="_5-各片型的分镜取向" tabindex="-1">⑤ 各片型的分镜取向 <a class="header-anchor" href="#_5-各片型的分镜取向" aria-label="Permalink to &quot;⑤ 各片型的分镜取向&quot;">​</a></h2><p>选定片型之后，分镜的走向也就定了。三条取向差异最大的：</p><table tabindex="0"><thead><tr><th></th><th>工艺解构片</th><th>感官 ASMR 片</th></tr></thead><tbody><tr><td><strong>结构骨架</strong></td><td>原料 → 工艺 → 结果 → 产品（线性因果）</td><td>强 → 更强 → 最强（感官递增，无叙事）</td></tr><tr><td><strong>第一个镜头</strong></td><td>可以铺垫，但别用抽象概念镜开场</td><td>必须是全片最馋的一镜</td></tr><tr><td><strong>色调</strong></td><td>冷调（工艺段）转暖调（成品段）</td><td>全程暖调，不做冷暖变化</td></tr><tr><td><strong>声音</strong></td><td>环境音为主，安静，衬托&quot;精密&quot;</td><td><strong>ASMR 音效为主，是主角不是配角</strong></td></tr><tr><td><strong>节奏</strong></td><td>慢，升格多</td><td>快切，但每一镜都是升格素材</td></tr><tr><td><strong>字幕</strong></td><td>需要——概念镜头单独看看不懂</td><td>尽量不要，画面自己说话</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">概念镜头不要放在最前面</p><p>案例 04 的复盘结论：镜头 2（悬浮的负压隐喻）放在第 3 秒，观众会困惑几秒钟，不知道在看什么。</p><p>**先给一个能看懂的画面建立上下文，再上抽象表达。**这一条对工艺片是通用的——工艺片天然要用隐喻，而隐喻需要上下文才成立。</p></div><hr><h2 id="_6-判断清单" tabindex="-1">⑥ 判断清单 <a class="header-anchor" href="#_6-判断清单" aria-label="Permalink to &quot;⑥ 判断清单&quot;">​</a></h2><p>下次拿到一个&quot;工艺不一样&quot;的产品，按这个顺序过一遍：</p><ol><li><strong>差异化落在哪一层？</strong> 口味层 / 工艺层 / 品牌层——决定片子要承载什么</li><li><strong>感官要素还剩几条？</strong> 逐条核对热、质感、光泽、动作。<strong>失效的不要硬拍</strong></li><li><strong>合规先砍一轮。</strong> 对比结构、健康暗示、功效宣称——先把不能做的划掉</li><li><strong>AI 长短板对一遍。</strong> 拍不到的画面 = 长板；真人、文字、精确渐变 = 短板，见 <a href="/tools/decision-tree">选型决策树</a></li><li><strong>投放场景决定时长和开头。</strong> 详情页可以铺垫，信息流不行</li><li><strong>剩下的片型不止一个？</strong> 做组合拳，共用素材</li></ol><hr><h2 id="可复用套路" tabindex="-1">可复用套路 <a class="header-anchor" href="#可复用套路" aria-label="Permalink to &quot;可复用套路&quot;">​</a></h2><ol><li><p>**片型是排除出来的，不是选出来的。**先用产品条件和合规边界砍掉不可行的，剩下的往往只有一两个。这比&quot;头脑风暴各种可能性&quot;高效得多。</p></li><li><p>**同品类不等于同拍法。**薯条和薯条脆看着是一类东西，但一个有热气一个没有，食欲感的抓手完全不同。<strong>逐条核对感官要素，不要凭品类印象套模板。</strong></p></li><li><p>**合规在工艺类项目里是筛子，不是检查项。**它决定哪些片型不能做，必须放在最前面。放在最后，被砍掉的不是文案而是整支片子。</p></li><li><p>**AI 让工艺片从最贵变成最便宜。**过去要进车间或做三维动画，现在生成就行。<strong>成本结构变了，片型的性价比排序也要跟着变</strong>——这是需要重新评估的，不能沿用旧经验。</p></li><li><p>**单支片子有缺口时，考虑组合拳而不是硬塞。**感官片讲不了工艺，工艺片不够馋——不要试图用一支片子解决两个问题，那会变成两头不到岸。<strong>两支片子共用素材，成本增加有限。</strong></p></li><li><p>**AI 做不好的，就不要用 AI 做。**真人口播这类内容，找真人拍成本更低风险更小。<strong>诚实划出能力边界，比硬撑更专业。</strong></p></li></ol><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>这个判断落地成的完整项目 → <a href="/cases/case-04-vf-fries-crisp">案例 04 · VF 工艺薯条脆</a></li><li>感官路线的完整拍法 → <a href="/cases/case-03-fries-social">案例 03 · 快餐薯条社媒短视频</a></li><li>片型定了之后怎么排分镜 → <a href="/method/storyboard">分镜设计</a></li><li>哪些镜头不能交给纯生成 → <a href="/tools/decision-tree">选型决策树</a></li><li>文案的合规检查方法 → <a href="/prompts/copywriting">广告文案与口播</a></li></ul>`,75)])])}const u=r(d,[["render",n]]);export{c as __pageData,u as default};
